// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class PackedDependentCostFormulaTest {

	@Test
	void d3_01DoublingInvocationsDoublesOnlyPerInvocationWork() {
		double ten = PackedCostEstimate.streamingDependentCost(7.0d, 10.0d, 0.25d, 2.0d, 10.0d,
				1.0d, 1.0d, 3.0d);
		double twenty = PackedCostEstimate.streamingDependentCost(7.0d, 20.0d, 0.25d, 2.0d, 10.0d,
				1.0d, 1.0d, 3.0d);

		assertEquals(110.0d, ten);
		assertEquals(210.0d, twenty);
		assertEquals(2.0d * (ten - 10.0d), twenty - 10.0d,
				"startup-once and output work must not be multiplied by the invocation count");
	}

	@Test
	void d3_02FirstMatchAndExhaustionHaveDifferentWork() {
		double allHits = PackedCostEstimate.streamingDependentCost(0.0d, 100.0d, 1.0d, 1.0d, 50.0d,
				0.0d, 0.0d, 0.0d);
		double allMisses = PackedCostEstimate.streamingDependentCost(0.0d, 100.0d, 0.0d, 1.0d, 50.0d,
				0.0d, 0.0d, 0.0d);

		assertEquals(100.0d, allHits);
		assertEquals(5_000.0d, allMisses);
	}

	@Test
	void d3_03PerfectCacheChargesOneMissAndRemainingHits() {
		double memoized = PackedCostEstimate.memoizedDependentCost(3.0d, 1.0d, 0.0d, 2.0d, 50.0d,
				99.0d, 0.1d, 0.0d, 0.0d, 0.5d, 0.5d, 4.0d);

		assertEquals(19.9d, memoized, 1.0e-12d);
	}

	@Test
	void d3_04EvictionsAddExplicitMissAndReplacementWork() {
		double retained = PackedCostEstimate.memoizedDependentCost(0.0d, 5.0d, 5.0d, 1.0d, 10.0d,
				90.0d, 0.1d, 0.0d, 2.0d, 0.0d, 0.0d, 0.0d);
		double evicting = PackedCostEstimate.memoizedDependentCost(0.0d, 10.0d, 10.0d, 1.0d, 10.0d,
				80.0d, 0.1d, 10.0d, 2.0d, 0.0d, 0.0d, 0.0d);

		assertEquals(64.0d, retained);
		assertEquals(138.0d, evicting);
		assertTrue(evicting > retained);
	}

	@Test
	void d3_05MaterializationCrossoverIsCostedDirectly() {
		double streaming = PackedCostEstimate.streamingDependentCost(0.0d, 100.0d, 0.5d, 1.0d, 20.0d,
				0.0d, 0.0d, 0.0d);
		double materialized = PackedCostEstimate.materializedDependentCost(0.0d, 1.0d, 80.0d,
				100.0d, 0.1d, 10.0d, 0.0d);

		assertEquals(1_050.0d, streaming);
		assertEquals(100.0d, materialized);
		assertTrue(materialized < streaming);
	}
}
